// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, type(uint128).max);
        address a = makeAddr("actorA");
        address b = makeAddr("actorB");

        vm.deal(a, amount);
        vm.prank(a);
        c.deposit{value: amount}();
        vm.deal(b, amount);
        vm.prank(b);
        c.deposit{value: amount}();

        vm.prank(a);
        c.withdrawAll();
        vm.prank(b);
        c.withdrawAll();

        // Rule: once every depositor has withdrawn, withdrawAll is a successful no-op
        // (credit is consumed exactly once). In the buggy version the stale credit
        // underflows `balance` and the extra call reverts.
        bool ok;
        vm.prank(a);
        try c.withdrawAll() { ok = true; } catch { ok = false; }
        assertTrue(ok);
    }
}
